21	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
22	type SeriesView struct {
23		Name   string            `json:"name"`
24		Labels map[string]string `json:"labels"`
25		Points []Point           `json:"points"`
26	}
