28	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
29	type QuerySeries struct {
30		Name    string            `json:"name"`
31		Labels  map[string]string `json:"labels"`
32		Count   int               `json:"count"`
33		Average float64           `json:"average"`
34	}
