66	// LineError 是一行（一批）输入失败后的结构化结果。
67	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
68	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
69	type LineError struct {
70		Status   string    `json:"status"`
71		Line     int       `json:"line,omitempty"`
72		Index    int       `json:"index,omitempty"`
73		Error    string    `json:"error"`
74		Conflict *Conflict `json:"conflict,omitempty"`
75	}
