		`{"op":"query","name":"m","start":0}`,                                               // 缺 end
		`{"op":"query","name":"m","start":0,"end":1,"extra":1}`,                             // 未知字段
		`{"op":"ingest","name":"m","start":0,"end":1}`,                                      // 未知 op
		`{"op":"write","name":"m","start":0,"end":1}`,                                       // 其他 op
		`{"op":7,"name":"m","start":0,"end":1}`,                                             // op 类型错误
